export const articles = [
  { slug: 'custom-box-structure-guide', number: '01', angle: 'Structure', image: '/structure/structure-1.webp', imageAlt: 'Magnetic book-style premium rigid box structure', title: 'How to Choose the Right Custom Box Structure', summary: 'Compare rigid, folding carton, drawer, magnetic and corrugated structures by presentation, protection, volume and production needs.', intro: 'The right box structure is a commercial decision as much as a visual one. It affects tooling, assembly, packing speed, shipping volume, protection and the way a customer first handles the product.', datePublished: '2026-08-15', dateModified: '2026-08-28', faq: [['What is the most common structure for luxury packaging?', 'Rigid boxes—particularly magnetic and lift-off lid structures—are the most common choice for luxury packaging because they offer strong visual impact, a controlled opening experience and reliable product protection.'], ['When should I choose a folding carton over a rigid box?', 'Folding cartons suit high-volume retail products where storage efficiency and freight cost matter. Rigid boxes suit lower-volume gifting, launches and premium presentation where the box itself is part of the brand experience.']], sections: [
    ['Start with the product and sales channel', 'Confirm finished internal dimensions in L × W × H, product weight, fragility, retail or e-commerce use, order quantity and destination. A premium retail launch may justify a rigid presentation box, while a high-volume product may need a folding carton or corrugated mailer.'],
    ['Common premium structures', 'Magnetic book-style rigid boxes create a strong reveal. Drawer boxes offer a controlled slide-out experience. Lift-off lid boxes are versatile and efficient to pack. Folding cartons reduce storage and freight volume. Corrugated structures add transport protection and can still carry premium printing.'],
    ['Balance presentation and logistics', 'A beautiful box that ships mostly empty space can increase total landed cost. Fold-flat constructions, removable inserts and optimized outer cartons may reduce storage and freight, but savings should be confirmed with packed dimensions, carton count, CBM and weight.'],
    ['What to confirm before sampling', 'Approve the exact structure name, internal size, board thickness, opening direction, closure, insert concept, print areas and intended packing method before producing a physical sample.'],
  ]},
  { slug: 'packaging-material-selection', number: '02', angle: 'Materials', image: '/sustainability/documented-sourcing.webp', imageAlt: 'Premium paper and board material samples', title: 'Packaging Material Selection for Premium Boxes', summary: 'Understand greyboard, paperboard, corrugated board, specialty paper and responsible material options without over-specifying cost.', intro: 'Material selection determines stiffness, print behavior, edge quality, weight and tactile character. The most expensive substrate is not automatically the most suitable one.', datePublished: '2026-08-15', dateModified: '2026-08-28', faq: [['What is greyboard and why is it used for rigid boxes?', 'Greyboard is a dense, recycled paperboard typically used as the structural core of rigid boxes. It provides stiffness, weight and a premium feel at a lower cost than virgin fibre board, and accepts wrapping papers for a finished exterior.'], ['Can I request FSC-certified materials for my packaging?', 'Yes. FSC-certified papers and boards are available for most structures. The certificate applies to specific material grades and suppliers, so the claim should be confirmed against the actual material specification for your project.']], sections: [
    ['Structural board', 'Rigid boxes commonly use greyboard selected by thickness and density. Folding cartons use paperboard chosen by caliper, stiffness and print surface. Corrugated packaging adds flute selection, compression strength and edge-crush considerations.'],
    ['Wrapping and face paper', 'Coated paper supports detailed offset printing and lamination. Uncoated and textured specialty papers create a more tactile, restrained appearance but may change color reproduction, foil performance and rub resistance.'],
    ['Liners and exposed edges', 'Inside liners affect opening feel, cleanliness and brand color continuity. Wrapped edges, corner construction and paper grain direction influence the finished appearance of premium rigid boxes.'],
    ['Responsible choices', 'FSC-certified papers, recycled content, molded pulp and paper-based inserts can reduce plastic use. Claims should match actual certificates and the complete material specification rather than relying on a generic eco label.'],
  ]},
  { slug: 'printing-finishing-guide', number: '03', angle: 'Print & Finish', image: '/capability-folding-cartons.webp', imageAlt: 'Premium cartons with refined print and finishing', title: 'Printing and Finishing for Luxury Packaging', summary: 'Use color, foil, embossing, debossing, spot UV and texture with production tolerances and brand consistency in mind.', intro: 'Finishing should reinforce hierarchy and touch, not simply add decoration. Every process introduces cost, setup requirements and production tolerances that should be considered during artwork development.', datePublished: '2026-08-16', dateModified: '2026-08-28', faq: [['What is the difference between foil stamping and embossing?', 'Foil stamping applies a metallic or pigment layer to the surface using heat and pressure, creating shine or color. Embossing raises the surface physically to create a three-dimensional texture. Both can be combined for a foil-stamped and embossed logo.'], ['Does spot UV work on uncoated paper?', 'Spot UV can be applied to uncoated paper but the result may appear less glossy and more textured than on coated stock. A test proof is recommended to confirm the visual effect and adhesion on the specific paper.']], sections: [
    ['Color control', 'Specify Pantone or process color intent, the substrate, coating and approved reference. The same ink can appear different on coated paper, uncoated paper and colored specialty stock. Physical proofs remain important for critical brand colors.'],
    ['Foil stamping', 'Metallic, pigment and holographic foils create high contrast without ink. Fine lines, large solid areas, seams and textured paper require different tooling and pressure considerations.'],
    ['Embossing and debossing', 'Raised or recessed details add a tactile focal point. Artwork depth, board backing, register with print or foil and the reverse-side impression should be reviewed before tooling.'],
    ['Lamination, varnish and spot effects', 'Matte or gloss lamination changes color and rub resistance. Spot UV can create contrast but needs practical registration tolerance. Avoid combining processes only because they are available; prioritize the brand’s main visual signal.'],
  ]},
  { slug: 'custom-inserts-product-protection', number: '04', angle: 'Insert & Protection', image: '/sustainability/paper-based-options.webp', imageAlt: 'Molded pulp and paperboard custom inserts', title: 'Custom Inserts: Presentation, Fit and Product Protection', summary: 'Select paper, molded pulp, EVA or fabric-covered inserts based on fit, fragility, sustainability and the desired unboxing experience.', intro: 'An insert is part of the packaging structure. It controls movement, protects vulnerable areas and establishes how the product is presented when the box opens.', datePublished: '2026-08-17', dateModified: '2026-08-28', faq: [['What insert material is best for glass bottles?', 'The right insert depends on bottle weight, fragility, presentation and sustainability target. Molded pulp and paperboard platforms improve recyclability; EVA or fabric-covered foam provides tighter cushioning for heavier or more delicate bottles.'], ['Can one insert hold multiple products in a gift set?', 'Yes, but each product needs its own cavity dimensioned from measured product sizes—not from a photo or nominal fill volume. The lid clearance, finger access and product sequence should be planned before the insert is engineered.']], sections: [
    ['Begin with real product dimensions', 'Use measured product dimensions, weight, center of gravity, tolerances and fragile points. Nominal capacity or a product photo is not enough to engineer a secure fit.'],
    ['Paper and molded pulp', 'Folded paperboard inserts offer printability and recyclability. Molded pulp supports complex forms and plastic reduction, but tooling, surface texture and dimensional tolerance must suit the product.'],
    ['Foam and fabric-covered inserts', 'EVA and other foams provide cushioning and precise cavities. Fabric or paper wrapping improves presentation. Density, thickness, odor, color transfer and adhesive performance should be sampled.'],
    ['Test the complete pack', 'Evaluate insertion and removal, shake movement, compression, drop risk and the outer shipping carton—not only the insert on a desk. Final performance depends on the complete packaging system.'],
  ]},
  { slug: 'rigid-box-vs-folding-carton', number: '05', angle: 'How to choose', image: '/structure/structure-2.webp', imageAlt: 'Comparison of rigid box and folding carton structures', title: 'Rigid Box vs Folding Carton: Which Structure Fits Your Packaging Project?', summary: 'Compare rigid boxes and folding cartons on cost, MOQ, presentation, logistics and production to decide which structure suits your product and budget.', intro: 'Choosing between a rigid box and a folding carton is one of the first structural decisions in a packaging project. The right answer depends on product value, order quantity, distribution method, budget and the role the packaging plays in the brand experience.', datePublished: '2026-08-28', dateModified: '2026-08-28', faq: [['Is a rigid box always more expensive than a folding carton?', 'Generally yes—rigid boxes use more material, require hand assembly and cannot be shipped flat. However, at low volumes the price gap narrows because rigid box tooling costs are often lower than folding carton die costs.'], ['Can a folding carton look premium?', 'Yes. Specialty papers, foil stamping, embossing and high-quality printing can make a folding carton feel premium. The key difference is structural weight and the opening experience, not print quality.']], sections: [
    ['Understanding the structural difference', 'A rigid box is built from thick greyboard (typically 1.5–3 mm) wrapped with printed or specialty paper. It holds its shape, feels substantial and cannot be flattened. A folding carton is printed and die-cut from a single sheet of paperboard (typically 0.3–0.6 mm), then shipped flat and erected during packing. This fundamental difference drives cost, logistics and presentation.'],
    ['Cost comparison: what drives the price gap', 'Rigid boxes cost more per unit because they use heavier board, require separate wrapping, often need hand assembly and ship in larger cartons. Folding cartons are machine-made, ship flat and pack efficiently. However, at quantities under 1,000 pieces, rigid box tooling is often simpler and cheaper than a folding carton die with multiple folds and locks. The price crossover depends on the specific structure, finishes and order volume.'],
    ['When to choose a rigid box', 'Choose a rigid box when the packaging is part of the product experience—luxury gifting, product launches, influencer kits, retail displays where the customer handles the box before purchase, or products that need structural protection beyond what a carton provides. Magnetic closures, drawer mechanisms and shoulder-neck designs are only possible with rigid construction.'],
    ['When to choose a folding carton', 'Choose a folding carton for high-volume retail products, subscription boxes, individual units where storage and freight efficiency matter, or products where the packaging is functional rather than experiential. Folding cartons are also the better choice when shelf display requires hanging tabs or when the product needs to be visible through a window cutout.'],
    ['Hybrid approaches', 'Some projects use both: a rigid box for the gift set or launch edition, and a folding carton for the individual refill or retail unit. A shared colour palette, logo position and paper texture can connect the two structures visually while serving different distribution needs.'],
  ]},
  { slug: 'custom-packaging-cost-guide', number: '06', angle: 'Budget', image: '/structure/structure-3.webp', imageAlt: 'Custom packaging cost planning with material samples', title: 'Understanding Custom Packaging Costs: What Drives the Price', summary: 'Learn what factors determine the unit price of custom packaging—materials, printing, structure, finishes, order quantity and hidden costs most buyers overlook.', intro: 'Custom packaging pricing is not a single number. It is the result of material selection, structural complexity, printing and finishing processes, order quantity, tooling and logistics. Understanding these factors helps you write a better brief and avoid surprises.', datePublished: '2026-08-28', dateModified: '2026-08-28', faq: [['How much does a custom rigid box cost per unit?', 'The unit price depends on size, board thickness, wrapping paper, printing, finishes, insert material and order quantity. A simple rigid box with one-colour printing might start from $2–4 per unit at 1,000 pieces, while a complex multi-finish box with custom insert can reach $8–15 or more.'], ['What is the cheapest way to start with custom packaging?', 'The most cost-effective starting point is usually a simple structure with standard dimensions, one or two print colours, no foil or embossing, and a paperboard insert. This reduces tooling, setup and material costs while still delivering a branded experience.']], sections: [
    ['Materials: the foundation of cost', 'The substrate is the largest cost component. Greyboard for rigid boxes is priced by thickness and density. Paperboard for folding cartons varies by caliper, coating and specialty finish. Wrapping papers range from standard coated stock to textured uncoated papers and soft-touch laminates. Each step up in material quality adds cost, but also changes the tactile and visual result.'],
    ['Printing and finishing: where costs escalate', 'Each print colour requires a separate plate and setup pass. Foil stamping needs a custom die and heated press. Embossing and debossing each need their own tooling. Spot UV requires a screen or plate. Lamination adds a per-square-metre cost. A design that uses four print colours, foil, embossing and spot UV will cost significantly more than a one-colour print with a single finish—but may be exactly what the brand requires.'],
    ['Quantity and the unit price curve', 'Unit price drops as quantity rises because fixed costs (tooling, setup, sampling) are spread across more pieces. However, the relationship is not linear. A jump from 500 to 1,000 units often reduces unit price by 20–35%, while going from 5,000 to 10,000 might only save 8–15%. The sweet spot depends on the structure and your storage capacity.'],
    ['Hidden costs buyers often overlook', 'Beyond the box itself, budget for: physical sampling (often $150–500 per sample), artwork adaptation and prepress, insert tooling for molded pulp, export packing and carton costs, freight and import duties, and quality inspection. These are real project costs that should be in the brief from the start.'],
    ['How to write a cost-effective brief', 'Share your product dimensions, target quantity, desired structure, finish references, delivery country and target budget range. A clear budget range helps the packaging consultant recommend the right material, finish and quantity combination—rather than guessing and presenting options that overshoot or undershoot your needs.'],
  ]},
  { slug: 'packaging-materials-guide', number: '07', angle: 'Materials', image: '/sustainability/documented-sourcing.webp', imageAlt: 'Packaging material samples: greyboard, SBS, kraft and corrugated board', title: 'A Brand Guide to Packaging Materials: Greyboard, SBS, Kraft and Corrugated', summary: 'Understand the differences between greyboard, SBS paperboard, kraft paper and corrugated board—how each material performs, when to use it and what it costs.', intro: 'The material you choose determines how the box feels, how it prints, how it protects and how much it costs. This guide explains the four most common packaging substrates so you can make informed decisions in your brief.', datePublished: '2026-08-28', dateModified: '2026-08-28', faq: [['What is the difference between SBS and greyboard?', 'SBS (Solid Bleached Sulphate) is a white, clay-coated paperboard made from bleached virgin fibre—it prints cleanly and is used for folding cartons. Greyboard is a thick, dense recycled board used as the structural core of rigid boxes—it is not printed directly but wrapped with paper.'], ['Is kraft paper suitable for luxury packaging?', 'Kraft can work for luxury packaging when paired with the right brand positioning—natural, artisanal or eco-forward brands often use kraft for its texture and raw character. It prints well in one or two colours and takes foil and embossing effectively, though colour reproduction differs from coated white stock.']], sections: [
    ['Greyboard: the backbone of rigid boxes', 'Greyboard is a dense, multi-ply recycled paperboard made from recovered fibres. It comes in thicknesses from 1 mm to 3 mm and provides the structural stiffness that gives rigid boxes their weight and premium feel. Greyboard is not a finish surface—it is always wrapped with printed or specialty paper. Its main qualities are density, stiffness and cost efficiency. When specifying greyboard, confirm thickness, density (measured in g/cm³) and whether it meets any recycled content requirements.'],
    ['SBS paperboard: the folding carton standard', 'SBS (Solid Bleached Sulphate) is a white, clay-coated paperboard made from bleached virgin wood pulp. It offers a smooth, bright printing surface, good stiffness at lower calipers and clean fold performance. SBS is the standard choice for folding cartons in cosmetics, fragrance and premium retail. Common calipers range from 300 to 450 microns. The clay coating supports sharp offset printing, foil adhesion and lamination.'],
    ['Kraft board: natural character, growing demand', 'Kraft board is made from unbleached virgin or recycled fibres. It has a natural brown colour, visible fibre texture and a tactile, artisanal character. Kraft is popular with brands that want to signal naturalness, sustainability or a handcrafted aesthetic. It prints well in one or two colours, takes foil stamping and embossing effectively, but does not reproduce full-colour photography as cleanly as SBS. Kraft is available in both folding carton and corrugated grades.'],
    ['Corrugated board: protection with branding potential', 'Corrugated board combines a fluted inner layer with flat outer liners. The flute size (E, B, C or micro-flute) determines thickness, cushioning and print surface quality. E-flute and micro-flute corrugated are thin enough for high-quality printing and are used for e-commerce mailers, subscription boxes and shipping cartons that still carry brand identity. Corrugated adds transport protection that paperboard cannot match, but has a more utilitarian visual character.'],
    ['Choosing between them', 'Greyboard is for rigid boxes where weight and presentation matter. SBS is for folding cartons where print quality and shelf presence matter. Kraft is for brands where natural texture and eco positioning matter. Corrugated is for products that need transit protection with branded exterior. Many projects combine materials—a rigid box with SBS insert, a corrugated shipper with a kraft-lined interior. The right combination depends on product needs, brand positioning and budget.'],
  ]},
  { slug: '5-things-before-ordering-custom-packaging', number: '08', angle: 'Buyer Guide', image: '/structure/structure-1.webp', imageAlt: 'Custom packaging planning with material samples', title: '5 Things Every Brand Should Know Before Ordering Custom Packaging', summary: 'Before you request a custom packaging quote, understand these five key factors that affect structure, cost, timeline and the final result.', intro: 'Ordering custom packaging for the first time can feel complex. But most of the confusion comes from not knowing what information to provide and what decisions to make upfront. These five points will help you prepare a better brief and get a more accurate quotation.', datePublished: '2026-08-31', dateModified: '2026-08-31', faq: [['What information do I need to provide for a packaging quote?', 'You need: finished internal dimensions (L × W × H in mm), product weight, order quantity, desired structure type, finish references, insert material preference, delivery country and target budget range.'], ['Can I order custom packaging if I have never done it before?', 'Yes. Many brands order custom packaging for the first time. A good packaging supplier will guide you through structure selection, material options and sampling. Start with a simple structure and expand from there.']], sections: [
    ['1. Know your product dimensions and weight', 'The single most important piece of information is your product’s finished internal dimensions in length × width × height (in millimetres). Not the outer dimensions—not the product dimensions from a website listing—but the actual measured size of the product that will sit inside the box. Also confirm the weight. A 50ml glass perfume bottle weighs very differently from a 50ml plastic serum bottle, and that weight affects insert design, board thickness and shipping cost.'],
    ['2. Understand the difference between structure types', 'A rigid box is a thick, hand-assembled box that holds its shape and feels premium. A folding carton is a printed, die-cut box that ships flat. A magnetic box has a hidden magnet closure. A drawer box slides open. Each structure has different costs, minimums and visual impacts. Before requesting a quote, spend five minutes looking at packaging structures on our site so you can name what you want—or at least describe what you like.'],
    ['3. Be realistic about quantity and budget', 'Most custom packaging projects start from 500–1,000 pieces. If you need 100 pieces, the per-unit cost will be very high because tooling and setup costs are spread across fewer units. Similarly, if your budget is $1 per box for a complex rigid box with foil and custom insert, that is not realistic. A clear budget range helps the packaging consultant recommend the right combination of structure, material and finishes.'],
    ['4. Plan for sampling before production', 'A physical sample is produced before mass production. This sample is your chance to check the structure, material, print color, finish quality and insert fit. Sampling typically takes 7–14 days and has a cost (often $100–500 depending on complexity). Never skip sampling—it is far cheaper to correct a sample than to fix a production run of 5,000 boxes.'],
    ['5. Think about shipping and storage from the start', 'A beautiful box that ships mostly empty space will cost more to ship. Fold-flat structures, optimized outer cartons and efficient packing reduce freight costs. If you are ordering 5,000 rigid boxes, ask about packed carton dimensions, CBM (cubic metre volume) and weight so you can estimate shipping costs before committing.'],
  ]},
  { slug: 'how-to-write-a-packaging-brief', number: '09', angle: 'Buyer Guide', image: '/structure/structure-4.webp', imageAlt: 'Packaging brief template with specifications', title: 'How to Write a Packaging Brief That Gets You an Accurate Quote', summary: 'A clear packaging brief helps your supplier provide accurate pricing, realistic timelines and the right structure recommendation. Here is what to include.', intro: 'The quality of your packaging quote depends on the quality of your brief. A vague request like "I need a nice box for my perfume" will get you a vague answer. A specific brief with dimensions, quantity, structure and finish preferences will get you a focused recommendation and accurate pricing.', datePublished: '2026-08-31', dateModified: '2026-08-31', faq: [['What format should I use for a packaging brief?', 'A simple document or email is fine. Include: product dimensions, quantity, structure preference, material, finishes, insert type, delivery country, target budget and any artwork files. Photos of reference packaging are helpful.'], ['Should I include my budget in the brief?', 'Yes, if you have one. A budget range helps the packaging consultant recommend the right material and finish combination. Without a budget, you may receive options that are over or under your expectations.']], sections: [
    ['Product information', 'Start with your product: what is it, what does it weigh, what are its dimensions (L × W × H in mm), is it fragile, does it have a cap or lid that adds height, and how will it be oriented in the box. If you have multiple products (like a gift set), list each item with its dimensions and weight.'],
    ['Structure and quantity', 'State your preferred structure if you have one (rigid box, magnetic box, drawer box, folding carton, etc.) or describe what you want the opening experience to feel like. State your target quantity. If you are flexible, give a range (e.g. 1,000–3,000 pieces). The quantity affects unit price, material options and production method.'],
    ['Materials and finishes', 'Describe the exterior material (coated paper, textured paper, kraft, etc.), the interior lining (if any) and the finishes you want (foil stamping color, embossing, debossing, spot UV, lamination). If you have reference photos of finishes you like, include them. If you are unsure, say so—your supplier can recommend options.'],
    ['Insert and protection', 'Describe how the product should be held in the box. Should it sit in a foam cavity, on a paper platform, in a fabric-lined tray? If you have specific sustainability requirements (no foam, paper-based only), state them here. Include whether the product needs to be visible when the box opens or hidden until the customer removes a layer.'],
    ['Delivery and timeline', 'State the delivery country and any target delivery date. If you have a product launch date or seasonal deadline, include it. This helps the supplier plan sampling, production and shipping realistically. Also state your preferred trade terms if you know them (FOB, CIF, DDP, etc.).'],
  ]},
  { slug: 'custom-packaging-sampling-process', number: '10', angle: 'Process', image: '/hero/how-we-work.webp', imageAlt: 'Custom packaging sampling and approval process', title: 'Custom Packaging Sampling: What to Expect and How to Approve', summary: 'Understand the sampling process for custom packaging: what a sample includes, how long it takes, what it costs and what to check before approving production.', intro: 'Sampling is the step between quotation and production. It is your chance to physically hold the packaging, check the structure, verify the print quality and confirm the insert fit before committing to a full production run. Understanding the sampling process helps you make faster, better decisions.', datePublished: '2026-08-31', dateModified: '2026-08-31', faq: [['How long does packaging sampling take?', 'A typical sample takes 7–14 working days depending on the structure complexity, material availability and finishing processes. Simple structures with standard materials may be faster. Complex multi-part structures or specialty materials may take longer.'], ['What should I check when reviewing a packaging sample?', 'Check: box dimensions match your product, opening and closing feel correct, insert holds the product securely, print colors match your brand, finish quality (foil, emboss) is clean, wrapped edges are neat, and the overall construction feels solid. Test with the actual product if possible.']], sections: [
    ['What is a packaging sample?', 'A packaging sample is a single physical unit (or small set) of your custom packaging produced before mass production. It shows you exactly what the finished packaging will look and feel like: the structure, material, print, finish, insert fit and overall quality. A sample is not a prototype—it is produced using the same or similar methods as mass production, so it is a reliable representation of the final result.'],
    ['Types of samples', 'There are typically two types: a structural sample (white or plain, showing the box shape, size, insert and construction without final printing) and a printed sample (with your artwork, finishes and final materials). Some projects only need a printed sample. Others—especially complex structures—benefit from approving the structure first, then the printed version.'],
    ['What to check when reviewing a sample', 'Use your actual product: insert it, remove it, open and close the box several times. Check dimensions, lid friction, magnet strength (if applicable), insert retention, print color accuracy against your Pantone references, foil adhesion, emboss depth, edge wrapping quality and overall visual impression. If something feels off, say so—this is the time to make changes.'],
    ['Common sample revisions', 'It is normal to request 1–2 rounds of revisions. Common changes include: adjusting insert cavity size, changing lid friction, modifying print color, adjusting foil position, changing paper texture or updating artwork placement. Each revision typically adds a few days to the timeline.'],
    ['Approving for production', 'Once you are satisfied with the sample, approve it in writing. This approval becomes the production reference. Production will follow the approved sample specification for dimensions, materials, print, finishes and construction. Any changes after approval may require a new sample and additional cost.'],
  ]},
  { slug: 'reduce-shipping-costs-rigid-boxes', number: '11', angle: 'Cost Saving', image: '/structure/structure-5.webp', imageAlt: 'Fold-flat rigid box design for reduced shipping volume', title: 'How to Reduce Shipping Costs for Custom Rigid Boxes', summary: 'Rigid boxes are bulky and expensive to ship. Learn practical ways to reduce freight costs without compromising packaging quality.', intro: 'Rigid boxes are the premium choice for luxury packaging, but they are also the most expensive to ship. A rigid box cannot be flattened, so it occupies the same volume whether it is empty or full. For orders of 1,000+ units, shipping costs can be a significant part of the total landed cost. Here are practical ways to reduce those costs.', datePublished: '2026-08-31', dateModified: '2026-08-31', faq: [['How much does it cost to ship rigid boxes internationally?', 'Shipping costs depend on volume (CBM), weight, destination and shipping method. A typical 1,000-unit order of rigid boxes might occupy 2–4 CBM. Sea freight is cheapest (often $300–800 per CBM depending on route), air freight is fastest but most expensive ($4–8 per kg). Always request packed carton dimensions from your supplier to calculate accurately.'], ['Can rigid boxes be shipped flat?', 'Standard rigid boxes cannot be shipped flat because they are pre-assembled. However, fold-flat rigid boxes are designed to ship flat and be assembled by the recipient. This can reduce shipping volume by 60–80%, but adds assembly time and may not suit all structures.']], sections: [
    ['Understand why rigid boxes are expensive to ship', 'A rigid box is assembled before shipping. It cannot be flattened or compressed. This means 1,000 rigid boxes occupy the same volume whether they are filled with product or empty. The shipping cost is calculated on volume (CBM) or weight, whichever is greater. For rigid boxes, volume is almost always the deciding factor.'],
    ['Use fold-flat rigid box structures', 'A fold-flat rigid box is designed to ship flat and be assembled by the recipient or your fulfillment team. It uses the same premium materials and finishes as a standard rigid box but reduces shipping volume by 60–80%. This structure works well for e-commerce, subscription boxes and brands that assemble packaging at their warehouse.'],
    ['Optimize outer carton packing', 'Ask your supplier for packed carton dimensions (L × W × H in cm), carton count, total CBM and total weight. Use this information to calculate freight costs before committing. Sometimes a small change in box dimensions (e.g. reducing height by 5mm) can allow more units per carton and reduce total volume significantly.'],
    ['Choose sea freight over air freight', 'Sea freight is typically 5–10x cheaper than air freight for bulky items like rigid boxes. If your timeline allows 20–35 days for shipping, sea freight is the most cost-effective option. For urgent orders, consider air freight for a small sample batch and sea freight for the main production.'],
    ['Consider a fold-flat + rigid box combination', 'For brands that need both premium presentation and cost-efficient shipping: use fold-flat structures for the main product line (e-commerce, retail refill) and rigid boxes for limited editions, gift sets and PR kits. This balances premium experience with shipping efficiency.'],
  ]},
  { slug: 'ppwr-packaging-requirements', number: '12', angle: 'PPWR / EU Regulation', image: '/hero/packaging-insights.webp', imageAlt: 'Packaging material samples and documentation for EU regulatory compliance', title: 'PPWR Packaging Requirements 2026: What Brands Need to Know', summary: 'A practical guide to Regulation (EU) 2025/40, including 2026 application, technical documentation, the EU Declaration of Conformity and key milestones toward 2030.', intro: 'The EU Packaging and Packaging Waste Regulation (PPWR), Regulation (EU) 2025/40, is changing how packaging placed on the European market is designed, documented and assessed. The Regulation entered into force on 11 February 2025 and applies from 12 August 2026, with important requirements introduced on a phased timetable. For brands buying custom packaging, the key question is no longer simply whether a box looks sustainable. Buyers increasingly need to understand what the packaging is made from, how it is constructed, what supporting documentation exists and which PPWR requirements apply to their role in the supply chain.', datePublished: '2026-09-01', dateModified: '2026-09-01', faq: [['What is the EU PPWR?', 'The PPWR is Regulation (EU) 2025/40, the Packaging and Packaging Waste Regulation. It establishes directly applicable EU-wide rules covering packaging sustainability, waste prevention, recyclability, labelling and conformity assessment responsibilities.'], ['When does PPWR apply?', 'The PPWR entered into force on 11 February 2025 and applies from 12 August 2026. Requirements are phased, and important additional measures apply from 2030 and later depending on the packaging type and specific obligation.'], ['What is the difference between PPWR 2026 and 2030?', '2026 marks general application of the Regulation. 2030 and later dates introduce additional requirements on topics such as packaging minimisation, recycled content, reuse and certain restrictions. Not all future measures became mandatory in 2026.'], ['What is PPWR technical documentation?', 'Technical documentation supports the conformity assessment process under Article 38 and Annex VII. It may include packaging descriptions, design and manufacturing information, material specifications, drawings, component details and relevant test or assessment information.'], ['What is the EU Declaration of Conformity for packaging?', 'Article 39 of the PPWR establishes the EU Declaration of Conformity. It is used to declare that the applicable requirements under Articles 5 to 12 have been met. Annex VIII provides the model structure for the declaration.'], ['Does PPWR apply to luxury packaging?', 'Yes, luxury and premium packaging placed on the EU market falls within the PPWR framework. Premium packaging often combines several materials — such as rigid board, wrapping paper, foil, magnets, inserts and fabric — which makes material identification, component documentation and recyclability-oriented design particularly relevant.']], sections: [
    ['What Is the EU PPWR?', 'The Packaging and Packaging Waste Regulation — known as the PPWR — is Regulation (EU) 2025/40. It replaces the long-standing Directive 94/62/EC framework and introduces directly applicable EU-wide packaging rules.<br/><br/>Unlike the earlier Directive, which required individual Member State transposition and allowed variation in implementation, the PPWR creates a single regulatory baseline across the European Union. Its stated objectives include reducing packaging waste, improving the circularity of packaging materials and harmonising the rules that apply to packaging placed on the EU market.<br/><br/>For brands and importers selling into the EU, this means that packaging compliance is no longer determined only by national interpretations. The same Regulation applies regardless of which EU country the packaging enters, although enforcement responsibilities may still sit with national authorities.'],
    ['What Changed on 12 August 2026?', 'The PPWR entered into force on 11 February 2025, but the key date for most practical application is 12 August 2026 — the date from which the Regulation applies.<br/><br/>This does not mean that every future PPWR requirement became mandatory on that date. The PPWR is phased. Some general obligations began applying from 2026, while more detailed requirements — including measures relating to packaging minimisation, recyclability performance, recycled plastic content, reuse and certain packaging restrictions — are scheduled for later dates, with 2030 being an important milestone.<br/><br/>For packaging buyers, the practical implication is that2026 should be treated as the starting point for documentation awareness and packaging information requirements, not as the single deadline for all future obligations.<br/><br/><strong>Key point:</strong> PPWR is already applicable, but its requirements are phased. 2026 and 2030 should not be treated as the same compliance deadline.'],
    ['PPWR 2026 vs 2030: Why the Dates Matter', 'Understanding the phased structure of the PPWR is important because it affects when specific requirements apply to specific types of packaging.<br/><br/><strong>2025</strong> — Regulation (EU) 2025/40 entered into force on 11 February 2025.<br/><br/><strong>2026</strong> — General application began on 12 August 2026. This includes the start of the broader regulatory framework, general obligations and certain documentation and conformity-related requirements.<br/><br/><strong>2030 and later</strong> — Important additional requirements and milestones apply on later dates. These may include measures relating to packaging minimisation, recyclability performance requirements, minimum recycled plastic content targets, reuse obligations and certain restrictions on specific packaging formats or components.<br/><br/>Exact dates and obligations depend on the particular requirement and the type of packaging concerned. Not every future 2030 measure applies to every package. This is why the 2026 and 2030 dates should be considered separately when reviewing a specific packaging project.'],
    ['Who Is Responsible for PPWR Compliance?', 'The PPWR assigns responsibilities to economic operators based on their role in the supply chain. The main roles include:<br/><br/><strong>Manufacturers</strong> — typically the entity that manufactures the packaging or has it designed or manufactured, and places it on the EU market under its own name or trademark.<br/><br/><strong>Importers</strong> — entities that place packaging from a third country on the EU market.<br/><br/><strong>Distributors</strong> — entities that make packaging available on the EU market within the supply chain.<br/><br/><strong>Packaging and material suppliers</strong> — suppliers may have information obligations depending on their position in the chain and the applicable requirements.<br/><br/>The PPWR legal role does not always equal the physical factory producing the box. In many supply chains — particularly those involving overseas manufacturing — the importer or the brand placing the product on the EU market may carry significant responsibility. Responsibilities depend on the particular supply-chain arrangement and how the packaging is placed on the EU market.<br/><br/>This article is intended as general information and does not constitute legal advice.'],
    ['What Packaging Buyers Should Ask Their Supplier For', 'PPWR preparation for a custom packaging project begins with knowing exactly what is being manufactured. Before production begins, buyers should aim to have a clear record of the packaging specification. The following information forms a practical starting point:<br/><br/><strong>Material composition</strong> — Identify every material used in the packaging, including board, wrapping paper, coatings, adhesives, inks, foils, magnets, plastic components and fabric where applicable.<br/><br/><strong>Component breakdown</strong> — List each component part separately: outer box, lid, base, tray, insert, liner, decorative elements, closures and any attached accessories.<br/><br/><strong>Packaging dimensions and weight</strong> — Record finished external and internal dimensions and weight where relevant.<br/><br/><strong>Structural drawing or dieline</strong> — Obtain the structural drawing, dieline or assembly reference used for manufacturing.<br/><br/><strong>Printing and finishing specifications</strong> — Document print method, colour references, foil type, embossing, lamination and any specialty finishes.<br/><br/><strong>Insert specifications</strong> — Record insert material, dimensions, cavity shape and any product-contact considerations.<br/><br/><strong>Supplier declarations and test reports</strong> — Request relevant material supplier declarations and test reports where available.<br/><br/><strong>Project identification and revision control</strong> — Maintain batch references, date stamps and document revision information.<br/><br/>These documents do not alone guarantee PPWR compliance, but they form the practical foundation for a packaging documentation record.'],
    ['What Is PPWR Technical Documentation?', 'Technical documentation is a central part of the conformity assessment framework established by the PPWR.<br/><br/>Article 38 of the Regulation provides for conformity assessment. For the packaging requirements set out under Articles 5 to 12, the applicable procedure follows Annex VII.<br/><br/>Technical documentation may include:<br/><br/>• A description of the packaging and its intended use<br/>• Design and manufacturing information, including drawings<br/>• Materials and component specifications<br/>• Relevant technical specifications<br/>• Supporting assessment or test information where applicable<br/><br/>The purpose of technical documentation is to demonstrate that the packaging has been assessed against the applicable requirements. The exact content depends on the packaging type, the specific requirement and the role of the economic operator.<br/><br/>For premium packaging buyers — particularly those sourcing complex multi-component structures — early identification of available technical information helps ensure that the necessary documentation can be assembled alongside the packaging development process rather than after production is complete.'],
    ['What Is the EU Declaration of Conformity for Packaging?', 'Article 39 of the PPWR establishes the EU Declaration of Conformity. This is the formal declaration stating that the applicable requirements under Articles 5 to 12 have been met through the conformity assessment process.<br/><br/>Annex VIII of the Regulation provides the model structure for the Declaration of Conformity. It is a specific regulatory instrument, not a generic third-party certificate.<br/><br/>The responsibility for issuing the EU Declaration of Conformity depends on who qualifies as the manufacturer for the particular packaging under the PPWR. In supply chains involving overseas manufacturing, the importer or the brand placing the product on the EU market may carry this responsibility.<br/><br/><strong>PPWR compliance should not be reduced to buying a generic "PPWR certificate."</strong> The conformity process is supported by the applicable technical documentation under Annex VII and the EU Declaration of Conformity requirements under Article 39 and Annex VIII.'],
    ['What Does PPWR Mean for Luxury Packaging?', 'Luxury and premium packaging often combines several materials within a single structure. A rigid presentation box, for example, may include:<br/><br/>• Rigid greyboard structure<br/>• Wrapped paper or specialty paper exterior<br/>• Foil stamping or metallic finishes<br/>• Magnetic closures<br/>• EVA, foam or fabric-covered inserts<br/>• Plastic trays or windows<br/>• Multiple adhesive bonds<br/><br/>Each material component may be subject to different recyclability, separability and documentation considerations under the PPWR framework. This makes material identification, component breakdown, separability assessment, minimisation review, recyclability-oriented design and supporting documentation especially important for premium packaging projects.<br/><br/>The PPWR does not automatically prohibit mixed-material packaging. The applicable requirements depend on the specific packaging, its materials, its intended use and the obligations relevant to the economic operator. What the Regulation does require is that packaging information and documentation are available to support the applicable assessment process.'],
    ['How Can Rigid Boxes Be Designed With PPWR in Mind?', 'The PPWR encourages a packaging development approach that considers material efficiency, component necessity and recyclability-oriented design from the start of the project. For rigid boxes, several practical principles can support this direction:<br/><br/>• Reduce unnecessary structural components where the design allows<br/>• Avoid excessive material use where function and product protection do not require it<br/>• Assess whether magnet, plastic and fabric elements are functionally necessary<br/>• Consider component separation at end of life<br/>• Document material composition clearly for each component<br/>• Avoid oversized packaging structures where the product does not require them<br/>• Balance premium presentation requirements with material efficiency<br/><br/>These considerations can support PPWR-oriented packaging development. They are not a substitute for formal compliance assessment, but they help ensure that the packaging design stage is aligned with the direction of the regulation. For brands buying rigid boxes for the EU market, early discussion of these points with the packaging supplier can help identify practical improvements before tooling and production.<br/><br/><a href="/packaging/custom-rigid-boxes">Explore custom rigid boxes →</a>'],
    ['PPWR Considerations for Perfume and Cosmetic Packaging', 'Perfume, fragrance, cosmetics, skincare and gift set packaging present particular PPWR-related considerations because these products often use highly finished, multi-component packaging structures.<br/><br/>A typical perfume box may combine a rigid board exterior, specialty wrapping paper, foil or embossing, a fitted insert for the bottle, secondary protection for the cap or accessories and printed or coated interior surfaces. Cosmetic gift sets may add additional trays, compartments, fabric linings or multi-product configurations.<br/><br/>Each component adds documentation, material identification and recyclability-assessment complexity. For buyers of premium fragrance and cosmetics packaging, early project planning should consider:<br/><br/>• Material composition across all components<br/>• Insert material and design choices<br/>• Whether decorative finishes affect recyclability pathways<br/>• Shipping protection and how it relates to packaging structure<br/>• The technical documentation record that will support the project<br/><br/>MTT supports perfume, fragrance, cosmetics and skincare packaging projects with component-level material information and manufacturing specifications.<br/><br/><a href="/industries/perfume-fragrance-packaging">Explore perfume packaging →</a><br/><br/><a href="/industries/cosmetics-skincare-packaging">Explore cosmetics packaging →</a>'],
    ['A Practical PPWR Packaging Checklist for Buyers', 'The following checklist provides a practical framework for gathering packaging information at different stages of a project. It does not replace formal legal or compliance assessment.<br/><br/><strong>Before requesting a quote:</strong><br/>□ Product dimensions and weight<br/>□ Packaging dimensions<br/>□ Destination EU market<br/>□ Required structure type<br/>□ Target quantity<br/>□ Material preferences<br/>□ Insert requirements<br/>□ Printing and finishing requirements<br/><br/><strong>Before approving a sample:</strong><br/>□ Confirm final structure and component list<br/>□ Confirm all material specifications<br/>□ Confirm decorative finishes<br/>□ Confirm dimensions and weight where relevant<br/>□ Confirm documentation requirements<br/><br/><strong>Before production and market placement:</strong><br/>□ Confirm applicable PPWR responsibilities for your role<br/>□ Assemble relevant technical information<br/>□ Confirm required declarations and documentation<br/>□ Retain project and material records<br/>□ Review relevant market requirements for your EU destination<br/><br/>Starting this process early — ideally before the first quotation — helps ensure that packaging documentation develops alongside the project rather than being assembled after production is complete.'],
    ['How MTT Supports EU-Bound Packaging Projects', 'MTT Packaging supports EU-bound custom packaging projects with manufacturing-side information such as material specifications, component breakdowns, structural information and relevant supplier documentation where available.<br/><br/>Our role is to help customers understand what is being manufactured and provide useful production information for their packaging documentation process. This includes identifying materials, recording component specifications and supporting the information-gathering process that forms part of a broader conformity assessment approach.<br/><br/>We work with brands, importers and packaging buyers who need clear manufacturing information for projects involving rigid boxes, folding cartons, paper bags, custom inserts and premium finishing — whether the packaging is destined for perfume, cosmetics, jewelry, gifting or other product categories.<br/><br/><strong>Explore PPWR Packaging Support:</strong><br/><a href="/ppwr-compliant-packaging">View MTT PPWR packaging support →</a><br/><br/><strong>Discuss an EU Packaging Project:</strong><br/><a href="/request-a-quote">Request a quote →</a><br/><br/><strong>Further reading:</strong><br/><a href="/packaging/custom-rigid-boxes">Custom rigid boxes</a><br/><a href="/packaging/folding-cartons">Folding cartons</a><br/><a href="/packaging/custom-inserts">Custom inserts</a><br/><a href="/sustainability">Sustainability approach</a><br/><br/><em>This guide is intended as general packaging information and is not legal advice. Applicable PPWR obligations depend on the packaging, materials, intended use and role of the relevant economic operator.</em>'],
    ['Official PPWR Sources', 'The following official sources provide authoritative information on the EU Packaging and Packaging Waste Regulation:<br/><br/><a href="https://eur-lex.europa.eu/eli/reg/2025/40/oj" target="_blank" rel="noopener noreferrer">Regulation (EU) 2025/40 — EUR-Lex ↗</a><br/><br/><a href="https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52026XC03084" target="_blank" rel="noopener noreferrer">European Commission PPWR Guidance ↗</a><br/><br/><a href="https://environment.ec.europa.eu/publications/faq-packaging-and-packaging-waste-regulation-ppwr_en" target="_blank" rel="noopener noreferrer">European Commission PPWR FAQ ↗</a><br/><br/>For specific compliance questions, consult the applicable Regulation text and seek independent legal or regulatory advice relevant to your packaging, market and supply-chain role.'],
  ]},

  { slug: 'molded-pulp-inserts-cosmetic-packaging', number: '13', angle: 'Insert Design', image: '/sustainability/paper-based-options.webp', imageAlt: 'Molded pulp insert designed for cosmetic packaging', title: 'Molded Pulp Inserts for Cosmetic Packaging: Design, Protection & Materials', summary: 'Learn how molded pulp inserts are designed for cosmetic and skincare packaging, including product fit, material selection, tooling, sampling and protective performance.', intro: 'A molded pulp insert should do more than fill empty space inside a box. It should locate the product, support important contact areas, protect against movement and handling, contribute to presentation and work together with the outer packaging structure. Insert design begins with the product and the distribution requirements — not with a generic cavity shape.', datePublished: '2026-09-03', dateModified: '2026-09-03', sections: [
    ['What Is a Molded Pulp Insert?', 'Molded pulp — sometimes called molded fiber — is a packaging material formed by shaping fibrous slurry into three-dimensional forms using custom molds. The raw material is typically recycled paper, cardboard or natural fibres such as bamboo or bagasse.<br/><br/>Different molded-fiber manufacturing processes can produce different levels of surface quality, detail, structural performance, dimensional consistency and presentation quality. Some processes produce thicker, more textured components suited to protective packaging. Others — including refined thermoformed or wet-pressed approaches — can achieve smoother surfaces and finer detail, making them worth considering for premium retail and cosmetic applications where appearance matters.<br/><br/>The right process depends on the product, the presentation target, the required dimensional precision and the packaging structure.'],
    ['Why Use Molded Pulp for Cosmetic Packaging?', 'Molded pulp inserts offer several characteristics relevant to cosmetic packaging projects:<br/><br/><strong>Product positioning</strong> — Custom cavities locate the product in a defined position inside the box, preventing movement during handling and transit.<br/><br/><strong>Structural support</strong> — The insert can be engineered to support specific contact areas such as the base of a bottle, the shoulder of a jar or the cap of a pump dispenser.<br/><br/><strong>Presentation</strong> — When the box opens, the insert is visible. A well-designed molded pulp insert contributes to the unboxing experience and can reinforce a paper-based, natural or premium brand aesthetic.<br/><br/><strong>Integration</strong> — Molded pulp inserts can be designed to fit inside rigid boxes, folding cartons or other outer packaging structures.<br/><br/><strong>Suitability</strong> — Selected skincare, cosmetics, fragrance and gift-set packaging projects can use molded pulp inserts effectively.<br/><br/><strong>Important:</strong> Not every product is automatically suitable for molded pulp. Very fragile, heavy, unusually shaped or highly tolerance-sensitive products may require another insert material or a hybrid solution. The decision should be based on the specific product, its geometry, weight and distribution environment.'],
    ['Molded Pulp vs Paperboard vs EVA Inserts', '<table class="comparison-table"><thead><tr><th>Attribute</th><th>Molded Pulp</th><th>Paperboard</th><th>EVA / Foam</th></tr></thead><tbody><tr><td>Structural approach</td><td>Three-dimensional molded form with custom cavities</td><td>Folded or die-cut platforms, trays and partitions</td><td>CNC-cut or die-cut cavities in foam sheets</td></tr><tr><td>Presentation</td><td>Natural, textured surface; can achieve smoother finish with refined processes</td><td>Clean, printable surface; visible fold lines</td><td>Smooth, uniform surface; can be wrapped in fabric or paper</td></tr><tr><td>Product fit</td><td>Custom-molded cavities shaped to product geometry</td><td>Approximate fit from folded or cut shapes</td><td>Precise cavities cut to product profile</td></tr><tr><td>Cushioning / protection</td><td>Moderate; depends on wall thickness, geometry and material density</td><td>Limited; primarily positioning rather than cushioning</td><td>Good cushioning; density and thickness are selectable</td></tr><tr><td>Customization</td><td>Requires tooling; geometry defined by mold design</td><td>Die-cut tooling; simpler geometry changes</td><td>CNC programming; geometry changes are relatively quick</td></tr><tr><td>Typical applications</td><td>Cosmetics, skincare, fragrance, gift sets, premium retail</td><td>High-volume retail, folding carton inserts, lightweight products</td><td>Delicate products, heavy items, electronics, precision fit</td></tr></tbody></table><br/>The right insert depends on the product, presentation target, distribution environment and packaging structure.'],
    ['How a Custom Molded Pulp Insert Is Developed', '<div class="process-timeline"><div class="process-step"><span class="process-number">1</span><div class="process-content"><strong>Product Information</strong><p>Collect product dimensions, weight, shape, fragile areas and component details such as bottle, cap, pump or glass elements.</p></div></div><div class="process-step"><span class="process-number">2</span><div class="process-content"><strong>Packaging Requirements</strong><p>Define the outer packaging structure, presentation target, distribution environment, quantity and market requirements.</p></div></div><div class="process-step"><span class="process-number">3</span><div class="process-content"><strong>Structural Concept</strong><p>Develop the initial insert concept including cavity layout, product orientation, support areas and how the insert fits the outer box.</p></div></div><div class="process-step"><span class="process-number">4</span><div class="process-content"><strong>Material / Process Selection</strong><p>Select the appropriate molded fiber process and material grade based on surface quality, structural and presentation requirements.</p></div></div><div class="process-step"><span class="process-number">5</span><div class="process-content"><strong>Engineering</strong><p>Develop detailed geometry including draft angles, radii, wall thickness, cavity depth and demolding considerations.</p></div></div><div class="process-step"><span class="process-number">6</span><div class="process-content"><strong>Tooling & Sampling</strong><p>Produce tooling and initial samples for physical evaluation with the actual product.</p></div></div><div class="process-step"><span class="process-number">7</span><div class="process-content"><strong>Fit Evaluation</strong><p>Test the actual product in the sample insert: check fit, clearance, holding force, insertion and removal.</p></div></div><div class="process-step"><span class="process-number">8</span><div class="process-content"><strong>Packaging / Transit Validation</strong><p>Evaluate the complete packed unit through handling, shake, compression and transit testing.</p></div></div><div class="process-step"><span class="process-number">9</span><div class="process-content"><strong>Revision</strong><p>Adjust geometry, clearance or cavity design based on evaluation results if required.</p></div></div><div class="process-step"><span class="process-number">10</span><div class="process-content"><strong>Production</strong><p>Approve the final sample and proceed to production with the confirmed specification.</p></div></div></div>'],
    ['Start With the Product — Not the Box', 'Effective insert engineering begins with the product itself. Before designing the insert, gather the following information:<br/><br/>• Product length, width and height<br/>• Product weight<br/>• Product shape and geometry<br/>• Fragile areas — glass components, pump dispensers, caps, lids<br/>• Bottle, jar, tube or compact dimensions where relevant<br/>• Intended product orientation in the packaging<br/>• Number of products in the set<br/>• Outer packaging constraints — internal dimensions of the box<br/>• Expected order quantity<br/>• Distribution environment — retail shelf, e-commerce shipping, gifting<br/><br/>The insert should be engineered around how the actual product needs to be supported, not simply shaped to look attractive on its own.'],
    ['Product Fit, Clearance and Manufacturing Tolerance', 'A molded pulp cavity should not simply copy the nominal product dimensions to create an identical cavity. Molded fiber manufacturing has inherent process variation, and the insert needs to accommodate that variation while still providing appropriate support.<br/><br/>Clearance and contact areas should be determined according to:<br/><br/>• Product geometry — simple cylinders require different treatment than complex multi-component forms<br/>• The selected molded fiber process — different processes have different dimensional consistency<br/>• Product weight — heavier products may require tighter support in specific areas<br/>• Critical contact areas — which parts of the product must be supported and which must be kept clear<br/>• Required holding force — the product should be secure but still removable<br/>• Sampling results — physical fit testing with actual products is essential<br/><br/>Final tolerance and clearance values are project-specific and should be confirmed through the sampling and evaluation process.'],
    ['Draft, Radii and Moldable Geometry', 'Molded fiber geometry must be designed to work with the selected manufacturing process. Several geometric considerations affect manufacturability:<br/><br/><strong>Draft</strong> — Draft angles help the formed part release from the mold. Insufficient draft can cause the part to stick or deform during demolding.<br/><br/><strong>Radii</strong> — Radiused transitions are generally preferable to sharp internal corners. Sharp internal geometry can be difficult to form cleanly and may create weak points in the finished part.<br/><br/><strong>Deep or narrow cavities</strong> — Cavities that are significantly deeper than they are wide may require engineering review, as material distribution and demolding become more challenging.<br/><br/><strong>Undercuts</strong> — Features that prevent straight-line removal from the mold can complicate tooling and may require additional mold components or process adjustments.<br/><br/><strong>Wall geometry</strong> — Wall thickness, taper and surface texture all affect how the material forms and how the finished part performs structurally.<br/><br/>Final geometry must be reviewed against the selected molded-fiber process and tooling approach. There are no universal numerical rules that apply across all processes and geometries.'],
    ['Presentation Matters in Premium Cosmetic Packaging', 'In premium cosmetic packaging, the insert is visible when the box opens. It becomes part of the brand presentation.<br/><br/>Several presentation factors can be considered during insert design:<br/><br/><strong>Surface finish</strong> — The texture and smoothness of the molded fiber surface. Different processes produce different surface characteristics.<br/><br/><strong>Texture</strong> — Some applications benefit from a visible fibre texture that communicates a natural, paper-based material. Others may prefer a smoother surface.<br/><br/><strong>Color</strong> — Molded pulp is available in different tones depending on the raw material. Some processes accept color application where appropriate.<br/><br/><strong>Product reveal</strong> — How the product is presented when the box opens. The cavity depth, product orientation and surrounding surface all contribute to the reveal.<br/><br/><strong>Alignment</strong> — Consistent positioning of the product within the box and alignment with other set components.<br/><br/><strong>Integration</strong> — How the insert fits within a rigid box, folding carton or other outer structure. The relationship between the insert and the box lining, edges and lid clearance.<br/><br/><strong>Branding details</strong> — Where technically suitable, some molded fiber processes can incorporate embossed or debossed details.<br/><br/>Available presentation options depend on the selected process and should be confirmed during the sampling stage.'],
    ['Sampling Before Production', 'Physical sampling is an essential step before committing to production. The typical sequence is:<br/><br/>• Engineering concept → tooling and sample production<br/>• Actual product fit check with physical samples<br/>• Visual evaluation of surface quality, texture and presentation<br/>• Packaging and protection evaluation — complete packed unit<br/>• Revision if required — geometry, clearance or cavity adjustments<br/>• Production approval<br/><br/>Physical product samples or accurate CAD files and drawings improve the development process significantly. The more precise the product information provided, the more accurately the insert can be engineered on the first sample iteration.<br/><br/>Sample development timelines and costs are project-specific and depend on the selected process, geometry complexity and tooling requirements.'],
    ['What Should You Send Your Packaging Supplier?', '<div class="checklist-section"><p>To begin a molded pulp insert project, prepare the following information:</p><ul class="checklist"><li>Product dimensions</li><li>Product weight</li><li>Product photos from multiple angles</li><li>CAD files or technical drawings if available</li><li>Number of products per set</li><li>Preferred box style and dimensions</li><li>Target order quantity</li><li>Target market</li><li>Protection requirements — fragility, transit conditions</li><li>Presentation requirements — surface finish, color, branding</li></ul></div><div class="cta-paths"><div class="cta-path"><h3>Not sure about the starting packaging size?</h3><p>Use our calculator to estimate box dimensions from your product measurements.</p><a href="/tools/box-size-calculator" class="button">Try the MTT Packaging Calculator</a></div><div class="cta-path"><h3>Already have product dimensions, CAD or an existing package?</h3><p>Send us your product information for a custom packaging review.</p><a href="/request-a-quote" class="button">Request a Custom Packaging Review</a></div></div>'],
  ]},
  { slug: 'perfume-box-inserts', number: '14', angle: 'Fragrance Packaging', image: '/industry/perfume.webp', imageAlt: 'Perfume bottle with fitted packaging insert in rigid box', title: 'Perfume Box Inserts: How to Protect and Present Glass Bottles', summary: 'Learn how perfume box inserts support glass bottles, protect caps and sprayers, control movement, and integrate with rigid boxes, cartons and fragrance gift sets.', intro: 'Perfume box inserts have two jobs: hold and protect the bottle during handling and distribution, and present the bottle correctly when the package is opened. A premium outer box cannot compensate for a poorly fitted insert. Perfume packaging should therefore be developed as a system — bottle → insert → outer presentation box → shipping protection — where each layer serves a defined role.', datePublished: '2026-09-04', dateModified: '2026-09-04', seoTitle: 'Perfume Box Inserts & Bottle Packaging | Design Guide', sections: [
    ['Why Perfume Bottles Need a Fitted Insert', 'Perfume bottles are often made from glass and may combine several challenging features: a heavy base, decorative cap, pump or sprayer mechanism, coated or printed surfaces, labels and unusual bottle geometry.<br/><br/>The insert should help to:<br/><br/>• Locate the bottle in a defined position inside the box<br/>• Reduce unwanted movement during handling<br/>• Support appropriate areas of the bottle body<br/>• Protect visible surfaces from contact with other packaging components<br/>• Maintain presentation when the box is opened<br/>• Allow practical product removal by the end customer<br/><br/>A fitted insert is not a generic cushion. It is a packaging component engineered around the specific bottle geometry, weight and distribution requirements.'],
    ['Start With the Bottle: Dimensions, Weight, Cap and Sprayer', 'Bottle capacity alone — for example 50 ml or 100 ml — is not sufficient information for packaging engineering. Bottles of the same nominal capacity can vary significantly in shape, height, weight and surface features.<br/><br/>Useful project information includes:<br/><br/>• Bottle length, width and depth<br/>• Body height<br/>• Total height with cap assembled<br/>• Filled weight where available<br/>• Bottle base geometry<br/>• Shoulder geometry<br/>• Neck dimensions where relevant<br/>• Cap dimensions and shape<br/>• Pump or sprayer projection height<br/>• Label or decorated surface locations<br/>• Intended product orientation in the packaging<br/><br/>The complete assembled bottle matters because the insert must accommodate the cap, pump and any decorative projection — not only the bottle body. A cap that is overlooked during development can create clearance, fit and closure problems downstream.'],
    ['Where Should the Insert Support the Bottle?', 'The insert should stabilise the bottle without clamping every surface. The objective is controlled support in the right areas while avoiding unnecessary pressure elsewhere.<br/><br/>Possible support areas may include:<br/><br/>• Bottle base — primary weight-bearing contact<br/>• Lower body — lateral restraint<br/>• Side walls — limiting side-to-side movement<br/>• Shoulder region — where appropriate for taller or heavier bottles<br/>• Neck support — where the bottle geometry or weight distribution requires it<br/><br/>The design should avoid applying pressure to labels, decorative coatings, fragile cap elements, pump components or printed surfaces. Finger access should also be considered so the product can be removed practically by the end customer.<br/><br/>The correct support strategy depends on bottle geometry, weight, orientation and the outer packaging structure. Sample validation is an important part of confirming whether the intended support approach works in practice.'],
    ['Perfume Insert Materials Compared', '<table class="comparison-table"><thead><tr><th>Attribute</th><th>Paperboard</th><th>Molded Pulp</th><th>EVA / Foam</th><th>Wrapped Tray</th></tr></thead><tbody><tr><td>Structural approach</td><td>Folded or die-cut platforms, trays and partitions</td><td>Three-dimensional molded form with custom cavities</td><td>CNC-cut or die-cut cavities in foam sheets</td><td>Rigid or formed base wrapped in paper or fabric</td></tr><tr><td>Product fit</td><td>Approximate fit from folded or cut shapes</td><td>Custom-molded cavities shaped to bottle geometry</td><td>Precise cavities cut to bottle profile</td><td>Fit determined by underlying structure</td></tr><tr><td>Presentation</td><td>Clean printable surface; visible fold structure</td><td>Natural textured surface; smoother finish possible with refined processes</td><td>Smooth, uniform surface; commonly wrapped in fabric or paper</td><td>Premium visual finish with paper or fabric covering</td></tr><tr><td>Cushioning / support</td><td>Limited; primarily positioning rather than cushioning</td><td>Moderate; depends on wall thickness and geometry</td><td>Good cushioning; density and thickness are selectable</td><td>Support depends on underlying base material</td></tr><tr><td>Branding possibilities</td><td>Printable surfaces; colour matching possible</td><td>Surface texture; limited print application</td><td>Usually branded through covering material</td><td>Full branding through wrapping material and print</td></tr><tr><td>Typical project fit</td><td>Lighter bottles; paper-led packaging; high-volume projects</td><td>Paper-based direction; moderate-weight bottles; gift sets</td><td>Heavier bottles; precision fit; delicate or complex shapes</td><td>Premium presentation priority; gift sets; launches</td></tr></tbody></table>'],
    ['Paperboard vs Molded Pulp vs EVA vs Wrapped Tray', '<strong>Paperboard</strong> inserts can be useful for folded or die-cut structures, lighter products, paper-led packaging directions and projects where printing or structural folding adds value. They offer good recyclability within paper waste streams but provide limited cushioning compared to other materials.<br/><br/><strong>Molded pulp</strong> inserts can provide three-dimensional paper-fiber support suitable for a range of bottle shapes. Surface finish, dimensional consistency and appearance depend on the specific molded-fiber manufacturing process selected. Some processes produce a more textured, natural surface; others can achieve a smoother finish suitable for premium retail presentation.<br/><br/><strong>EVA and foam</strong> inserts can provide accurately cut cavities and cushioning support suitable for heavier, fragile or geometrically complex bottles. Presentation can be enhanced by covering with fabric, paper or flocking depending on the project requirements.<br/><br/><strong>Wrapped trays</strong> can be useful where premium visual presentation is a major priority, provided the underlying structure provides suitable product support and the bottle is adequately held in position.<br/><br/>The correct material depends on bottle weight, geometry, presentation target, outer box structure, distribution environment and project requirements.'],
    ['Matching the Insert to the Box Structure', 'The same perfume bottle may require different insert engineering depending on the outer package structure. The outer box determines how the insert sits, how the package opens, what clearance exists and what forces act on the product during use.<br/><br/><strong>Rigid lid-and-base box</strong> — the insert must position the bottle correctly in the base while the lid is removed. Product height and cap clearance relative to the inner lid surface should be reviewed.<br/><br/><strong>Magnetic closure rigid box</strong> — bottle position and top clearance must work with the closing mechanism. Magnets and closing geometry should not contact the bottle or cap.<br/><br/><strong>Drawer box</strong> — the insert must remain stable during pull-out movement. Lateral restraint becomes particularly important as the drawer action applies shear force to the product.<br/><br/><strong>Folding carton</strong> — the insert and carton structure should work together without unnecessary bulk. Insert stiffness and retention must be sufficient for the lighter carton structure.<br/><br/>The outer structure also determines lid clearance, opening direction and how the product is revealed. These should be considered together rather than designing the insert in isolation from the box.<br/><br/><a href="/packaging/custom-rigid-boxes">Explore custom rigid boxes →</a>'],
    ['Top Clearance and Cap Protection', 'Many perfume bottles have a decorative cap, sprayer or pump that projects above the bottle body. This projection is often the most visually distinctive part of the product — and often the most vulnerable to contact damage.<br/><br/>The complete package should be reviewed so the cap, sprayer or pump is not unintentionally loaded by the lid or top panel when the box is closed. This requires understanding:<br/><br/>• Complete bottle height including all assembled components<br/>• Cap height and shape<br/>• Insert display height — where the bottle sits relative to the box base<br/>• Inner lid clearance available in the outer box<br/>• Bottle movement range under handling forces<br/>• Closing action and how the lid engages with the base<br/><br/>If the cap projection is taller than the available inner clearance, the lid may contact the cap during closing. This can cause scratching, loosening or mechanical stress on the pump mechanism.<br/><br/>Specific clearance values are not universal — they depend on bottle geometry, box structure, insert depth and the closing characteristics of the outer box.'],
    ['Single Bottle vs Discovery Set Inserts', 'Single perfume bottles, two-bottle gift sets, miniature fragrance sets and discovery or sample vial configurations all require different insert engineering.<br/><br/><strong>Single bottle</strong> — the insert should locate the bottle, support appropriate surfaces and present it cleanly when the box opens. The cavity geometry follows the bottle profile.<br/><br/><strong>Bottle plus accessory</strong> — when a box holds a bottle alongside a travel spray, miniature or cosmetic accessory, each product needs its own cavity dimensioned from measured product dimensions.<br/><br/><strong>Two-bottle gift set or miniature set</strong> — cavity spacing, visual alignment and product sequence contribute to presentation. The insert should allow practical finger access to remove each product without disturbing the others.<br/><br/><strong>Discovery or sample vial set</strong> — multiple smaller cavities must hold each vial securely while remaining accessible. Weight distribution across the insert becomes more important as the number of products increases.<br/><br/>Accessories, booklets, cards or printed materials that accompany the set should also be accommodated in the insert design where relevant.'],
    ['Sampling and Fit Testing', 'The typical development sequence for perfume box insert projects follows a practical engineering process:<br/><br/><div class="process-timeline"><div class="process-step"><span class="process-number">1</span><div class="process-content"><strong>Bottle Information</strong><p>Collect dimensions, weight, component details and photos of the assembled bottle.</p></div></div><div class="process-step"><span class="process-number">2</span><div class="process-content"><strong>Structural Concept</strong><p>Define the outer box structure, insert material direction and product orientation.</p></div></div><div class="process-step"><span class="process-number">3</span><div class="process-content"><strong>Insert Engineering</strong><p>Develop cavity geometry, support areas, clearance and retention characteristics.</p></div></div><div class="process-step"><span class="process-number">4</span><div class="process-content"><strong>Prototype Sample</strong><p>Produce a physical insert sample for evaluation.</p></div></div><div class="process-step"><span class="process-number">5</span><div class="process-content"><strong>Bottle Fit Check</strong><p>Test the actual bottle in the sample insert: fit, clearance, holding force, insertion and removal.</p></div></div><div class="process-step"><span class="process-number">6</span><div class="process-content"><strong>Box Closure Check</strong><p>Confirm the complete packed unit closes correctly with the bottle, insert and lid clearance.</p></div></div><div class="process-step"><span class="process-number">7</span><div class="process-content"><strong>Visual Evaluation</strong><p>Assess presentation, alignment and overall visual impression when the box opens.</p></div></div><div class="process-step"><span class="process-number">8</span><div class="process-content"><strong>Handling Review</strong><p>Evaluate practical removal and replace behaviour as the end customer would experience it.</p></div></div><div class="process-step"><span class="process-number">9</span><div class="process-content"><strong>Revision</strong><p>Adjust cavity geometry, clearance or support areas based on evaluation results.</p></div></div><div class="process-step"><span class="process-number">10</span><div class="process-content"><strong>Production Approval</strong><p>Confirm the final sample specification for production.</p></div></div></div>A real bottle sample is highly useful for fit testing. If unavailable, accurate CAD files, technical drawings and weight information improve the development process.'],
    ['Presentation Packaging vs Shipping Protection', 'A premium perfume presentation box and insert are not automatically a complete shipping system. These are two different packaging functions with different engineering requirements.<br/><br/><strong>Primary / presentation packaging</strong> — the rigid box, insert and product reveal. This is the packaging the customer sees and handles. Its role is product presentation, brand experience and product holding.<br/><br/><strong>Transport packaging</strong> — the corrugated shipper, mailer or outer transit carton. This is the packaging that protects during warehousing, distribution and delivery. Its role is protection against transit forces, stacking compression and handling impact.<br/><br/>Depending on the sales and distribution method, additional protection may be required. A perfume box shipped by e-commerce needs a different outer protection approach than a product displayed on a retail shelf.<br/><br/>The presentation packaging should be developed first around the bottle, the brand experience and the opening moment. The transport layer should then be engineered around the packed presentation box, its weight, fragility and distribution environment.'],
    ['What Should You Send Your Packaging Supplier?', '<div class="checklist-section"><p>To begin developing perfume box inserts, prepare the following information:</p><ul class="checklist"><li>Bottle dimensions — length, width, depth</li><li>Total height including cap</li><li>Filled weight if available</li><li>Product photos from multiple angles</li><li>CAD or technical drawings if available</li><li>Cap, pump and sprayer details</li><li>Bottle surface and label information</li><li>Number of products per set</li><li>Preferred outer packaging structure</li><li>Preferred insert material direction if known</li><li>Target order quantity</li><li>Destination or target market</li><li>Presentation requirements</li><li>Distribution method — retail, e-commerce or gifting</li><li>Reference packaging if available</li></ul></div><div class="cta-paths"><div class="cta-path"><h3>Still Working Out the Packaging Size?</h3><p>Use the MTT Packaging Calculator to estimate box dimensions from your product measurements.</p><a href="/tools/box-size-calculator" class="button">Try the MTT Packaging Calculator</a></div><div class="cta-path"><h3>Already Have Bottle Dimensions or CAD?</h3><p>Send us your bottle information for a custom packaging review and insert recommendation.</p><a href="/request-a-quote" class="button">Request a Custom Packaging Review</a></div></div>'],
    ['Develop Your Perfume Packaging With MTT', 'MTT Packaging can review bottle information, packaging structure and insert requirements to help establish an appropriate packaging direction for your perfume product. Whether you have finalised bottle dimensions, CAD files or an early-stage concept, we can work with your information to develop insert engineering and outer packaging that fits your product and your market.<br/><br/><a href="/request-a-quote" class="button">Request a Quote</a><br/><br/><a href="/industries/perfume-fragrance-packaging">Explore perfume &amp; fragrance packaging →</a>'],
  ]},
] as const;
export function getArticle(slug: string) { return articles.find((article) => article.slug === slug); }
